import React from "react";
import "./Landlord.css"; 
import { useNavigate } from "react-router-dom"; // for navigation (if using React Router)
import { ArrowRight } from "lucide-react"; // modern icon option

export default function Landlord() {
  const navigate = useNavigate();

  const landlords = [
    {
      name: "Rizal Boardinghouse",
      address: "Gen. Luna, La Paz Iloilo city",
      avatar: "avatar1.png",
    },
    {
      name: "Magss Boarding House",
      address: "Burgos St. Lapaz Iloilo city",
      avatar: "avatar2.png",
    },
    {
      name: "Tanya Boardinghouse",
      address: "Brgy Tacas, Jaro, Iloilo city",
      avatar: "avatar3.png",
    },
    {
      name: "Sarrah Boardinghouse",
      address: "Iloilo city",
      avatar: "avatar4.png",
    },
  ];

  // Example click handler
  const handleViewClick = (landlord) => {
    // Later you can replace this with:
    // navigate(`/landlord/${landlord.name}`);
    alert(`Viewing info for ${landlord.name}`);
  };

  return (
    <div className="bg-white text-black min-h-screen">
      <nav className="navbar">
        <div className="nav-left">
          {/* Add navigation or logo if needed */}
        </div>
      </nav>

      {/* Main Content */}
      <section className="main-section">
        <h2 className="section-title">See Landlords Info</h2>

        <div className="landlord-list">
          {landlords.map((landlord, index) => (
            <div key={index} className="landlord-card">
              <div className="landlord-info">
                <img
                  src={landlord.avatar}
                  alt="Avatar"
                  className="avatar"
                />
                <div>
                  <p className="landlord-name">
                    {landlord.name}
                    <span className="verified-dot">●</span>
                  </p>
                  <p className="landlord-address">{landlord.address}</p>
                </div>
              </div>

              <button
                className="view-btn"
                onClick={() => handleViewClick(landlord)}
              >
                <ArrowRight size={18} />
              </button>
            </div>
          ))}
        </div>
      </section>

      <footer className="footer">
        © 2025 RenterGo. All rights reserved.
      </footer>
    </div>
  );
}
